# Compare zero-work layout page minimum with a direct page-only DP.
import subprocess, random, functools
WIDTH=[16,8,4]
def pages(s,b,m):
 K=s if b==0 else b-1
 return (32+4*b+K*WIDTH[m]+63)//64
def comps(s):
 for b in range(2,min(9,s)+1):
  def rec(rem,k,p):
   if k==1:yield p+[rem]
   else:
    for x in range(1,rem-k+2):yield from rec(rem-x,k-1,p+[x])
  yield from rec(s,b,[])
def mins(st):
 R=len(st)
 @functools.lru_cache(None)
 def f(i,j):
  s=j-i;sp=st[j-1]-st[i];lg=[0]
  if sp<1<<64:lg.append(1)
  if sp<1<<32:lg.append(2)
  best=10**9
  if s<=8:
   for m in lg:best=min(best,pages(s,0,m))
  for co in comps(s):
   pos=i;tot=pages(s,len(co),min(lg)) # mode page nonincreasing by width, min legal mode likely smallest pages
   for x in co:tot+=f(pos,pos+x);pos+=x
   best=min(best,tot)
  return best
 return f(0,R)
def runplan(st):
 lines=['PLAN 1',f'0 1 1 0 0 0 1 0',str(len(st))]+[f'{x:032x} {i%7}' for i,x in enumerate(st)]
 p=subprocess.run(['tmp/engine_test'],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode:raise RuntimeError(p.stderr.decode())
 o=p.stdout.decode().splitlines();return tuple(map(int,o[-1].split()))
random.seed(9)
for R in range(1,13):
 for trial in range(20):
  st=[0]
  for i in range(R-1):st.append(st[-1]+random.randint(1,random.choice([1,10,1<<33,1<<65])))
  exp=(0,1+(4*R+63)//64+mins(st))
  got=runplan(st)
  if got!=exp:
   print('FAIL',R,trial,got,exp,list(map(hex,st)));raise SystemExit(1)
print('PAGE-ONLY MIN PASS')
